import{_ as n,l as o,o as t,c as l,v as e,p as s,x as i,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"跳过程直觉","description":"","frontmatter":{"title":"跳过程直觉","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/jump-process-intuition.md","filePath":"quant/jump-process-intuition.md","lastUpdated":1789023840000}'),E={name:"quant/jump-process-intuition.md"};function h(u,a,c,_,B,A){const r=o("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="跳过程直觉" tabindex="-1">跳过程直觉 <a class="header-anchor" href="#跳过程直觉" aria-label="Permalink to &quot;跳过程直觉&quot;">​</a></h1><div class="epigraph"><p>连续半鞅的路径几乎必然连续。跳把有限变差或补偿泊松随机测度加进 $X$，二次变差多一项 $\\sum(\\Delta X)^2$，市场通常不再完备。</p><footer>—— 据 Merton, Journal of Financial Economics, 1976；Cont and Tankov, Financial Modelling with Jump Processes, 2004；Shreve, Stochastic Calculus for Finance II, 第 11 章整理</footer></div><p>上一课<a href="/quant/vol-as-input">波动率是输入不是输出</a>说明微笑拒绝单一 GBM。缺口的一条路径是让 \\(S\\) 可以跳：短到期虚值期权的厚尾不必全靠把 \\(\\sigma\\) 推到极大。本课只给跳的接口——复合泊松、二次变差的跳部分、对完备性的破坏——不把 Merton 公式或 Lévy 校准写成主干。后课美式、MC 若碰到跳，只调用这些对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布朗路径连续，\\(S\\) 不能在瞬时跨越障碍或跳过行权价。市场在公告、违约、宏观事件上会看到缺口。缺口是：在 SDE 里加一项 \\(J\\,\\mathrm d N\\)，或更一般地对泊松随机测度积分，使 \\(\\Delta S\\neq 0\\)。Itô 公式必须补 \\(f(X+\\Delta X)-f(X)-f_x\\Delta X\\)，二次变差 \\([X]_t=[X]^c_t+\\sum_{s\\le t}(\\Delta X_s)^2\\)。连续部分仍由扩散系数贡献；跳幅平方单独记账。</p><p>本课不重推布朗公理。连续情形已经够用的课继续用 GBM；这里只声明何时连续假设坏掉。</p><h3 id="跳不是「很大的日收益率」" tabindex="-1">跳不是「很大的日收益率」 <a class="header-anchor" href="#跳不是「很大的日收益率」" aria-label="Permalink to &quot;跳不是「很大的日收益率」&quot;">​</a></h3><p>离散采样的布朗也会有大增量，那是高斯尾，不是路径间断。跳是路径在某一 \\(t\\) 左极限与右极限不等。把日收益超过 \\(3\\sigma\\) 叫做跳，是统计规则，不是半鞅分解。定价接口要的是 \\(\\Delta X\\)，不是分位数标签。</p><p><span class="marginnote">Merton 1976 用复合泊松乘在股价上，在给定跳测度时仍可写期望；跳测度不能被连续交易完全对冲，故一般不完备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最简接口：\\(\\mathrm d S/S=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W+J\\,\\mathrm d N\\)，其中 \\(N\\) 是强度 \\(\\lambda\\) 的泊松过程，\\(J\\gt -1\\)。补偿后 \\(\\mathrm d N-\\lambda\\mathrm d t\\) 是鞅。风险中性下，\\(\\mu\\) 与跳补偿必须一起调整，使贴现 \\(S\\) 为局部鞅；如何拆开扩散溢价与跳溢价，是选 \\(Q\\)，不是唯一。特征函数在指数仿射时可用，便于欧式；路径依赖与美式通常走蒙特卡洛或树。</p><p>PIDE：Feynman–Kac 的局部项之外加积分项 \\(\\lambda\\int\\bigl(V(t,S(1+J))-V\\bigr)\\nu(\\mathrm d J)\\)。PDE 课的二阶算子不够。</p>',12)),(t(),s(p,null,{default:i(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E5%8D%8A%E9%9E%85%22%5D%20--%3E%20JUMP%5B%22%E5%8A%A0%E4%B8%8A%E8%B7%B3%E6%B5%8B%E5%BA%A6%22%5D%0A%20%20JUMP%20--%3E%20QV%5B%22%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%E5%A4%9A%E8%B7%B3%E5%B9%85%E5%B9%B3%E6%96%B9%22%5D%0A%20%20JUMP%20--%3E%20INC%5B%22%E4%B8%80%E8%88%AC%E4%B8%8D%E5%AE%8C%E5%A4%87%22%5D%0A%20%20INC%20--%3E%20AM%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%BE%8E%E5%BC%8F%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>泊松到来时刻是停时，但跳幅在到来瞬间实现，连续持仓 \\(\\Delta=V_S\\) 只能对冲瞬时扩散，对 \\(\\Delta S\\) 的非线性暴露（Gamma 在跳上变成有限差）留在组合里。这就是不完备的交易内容。若市场额外交易足够多的期权，可以把跳风险也跨到期对冲，那是把期权本身当成可交易标的，模型的「完备」是在放大的市场上说的。短到期虚值看涨对向下跳并不敏感、对向上跳极敏感，微笑的期限结构因此可以在不把扩散 \\(\\sigma\\) 推到极大的情况下变陡。</p><p>无穷活动 Lévy（无限小跳）让有限时间里有无穷次小跳，路径仍然 cadlag。主干直觉不需要这些分类，只需：有跳则乘法表与复制都要改。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准 CGMY，不写傅立叶定价的全部轮廓。违约跳与信用是另一门课。后课默认：连续扩散定价仍用到目前为止的 BSM 接口；一旦允许跳，价格是区间或依赖跳测度的选取，数值上用 PIDE 或带跳的路径模拟。跳只给后课接口，不在本课写成新的主干闭式。下一课<a href="/quant/american-optimal-stop">美式提前行权与最优停</a>在连续情形给出最优停接口，跳只作为「自由边界更难」的注。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跳是路径间断，\\(\\Delta X\\neq 0\\)；不是大日收益的别名。</li><li>二次变差多 \\(\\sum(\\Delta X)^2\\)；Itô 多有限差项。</li><li>连续对冲消不掉跳，市场一般不完备。</li><li>欧式可用特征函数；其余留给 MC / PIDE。</li><li>出处：Merton 1976；Cont–Tankov 2004；Shreve SDE II 第 11 章。</li></ul>',7))])}const S=n(E,[["render",h]]);export{f as __pageData,S as default};
